#include <iostream>
#include <memory>
struct Widget { Widget(){ std::cout << "Widget ctor\n"; } ~Widget(){ std::cout << "Widget dtor\n"; } };
std::unique_ptr<Widget> make_widget() { return std::make_unique<Widget>(); }  // 按值返回触发移动
int main() {
    auto w = make_widget();
    std::cout << "got widget\n";
}                                       // w 离开作用域自动析构 Widget
